package assets

import _ "embed"

// The shipped faces are SUBSETS of stock Inter, generated by
// scripts/subset_fonts.mjs (make gen-fonts) and committed alongside the full
// originals in fonts/.
//
// Stock Inter carries 2,851 reachable glyphs; Beatmo can render ~1,100 of them.
// The rest -- Cyrillic, Greek Extended, Vietnamese, IPA, and ~740 private-use
// alternates -- are dead weight in main.wasm, which ships every embedded byte to
// every visitor. Subsetting halves both faces (812 KiB -> 495 KiB raw,
// 397 KiB -> 236 KiB gzip) and gzip is the tight budget in
// internal/deploy/asset_size_test.go.
//
// Only EN and ES locales ship. A future non-Latin locale does NOT widen these
// files: i18n's FontProvider seam swaps the whole face per locale (see
// i18n.SetFontProvider and its "cjk" test case), so a CJK face would be its own
// asset loaded for that locale alone.
//
// fonts_coverage_test.go pins what these subsets must contain, so narrowing
// KEEP_RANGES in the script cannot silently ship tofu.

//go:embed fonts/Inter-Regular.subset.ttf
var GoRegularTTF []byte

//go:embed fonts/Inter-SemiBold.subset.ttf
var GoBoldTTF []byte
